package ai.eva.android.probe;
import android.app.*;import android.content.*;import android.os.*;import android.widget.*;import android.net.Uri;import java.io.*;import java.util.*;import java.util.concurrent.*;import org.json.*;
public class NetworkCaptureActivity extends ToolPageActivity {
 static final String ENGINE="com.emanuelef.remote_capture";TextView status,output;EditText filter,query,goal;CheckBox decrypt;final Handler tick=new Handler();final ExecutorService work=Executors.newSingleThreadExecutor();boolean requesting;final Runnable refresh=new Runnable(){public void run(){showStatus();tick.postDelayed(this,1000);}};
 public void onCreate(Bundle b){super.onCreate(b);page("网络采集与分析","");root.removeView(body);ScrollView scroll=new ScrollView(this);scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));body.addView(label("本机 VPN 采集 · PCAPdroid 引擎",18));body.addView(label("PCAP 保存到 Eva 工作区；Eva 自动配置目标、保存 PCAP 和 HTTP 结果；根据实际响应确认解密与商品内容。",13));status=label("",13);body.addView(status);Spinner scopes=new Spinner(this);scopes.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"仅美团","全机流量","仅 Eva（验证）","自定义包名"}));filter=new EditText(this);filter.setSingleLine();filter.setHint("留空表示全机；多个包名用逗号分隔");filter.setText("com.sankuai.meituan");scopes.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,android.view.View v,int n,long id){if(n<3)filter.setText(n==0?"com.sankuai.meituan":n==1?"":getPackageName());}});body.addView(scopes);body.addView(filter);goal=new EditText(this);goal.setHint("想抓取的内容，例如猪脚饭商品名称、价格和规格");body.addView(goal);decrypt=new CheckBox(this);decrypt.setText("尝试 HTTPS 解密并自动读取响应");decrypt.setChecked(true);body.addView(decrypt);body.addView(button("开始采集",()->startCapture()));body.addView(button("停止采集",()->command("stop",902)));body.addView(button("检查引擎状态",()->command("get_status",903)));body.addView(button("分析最近 PCAP",()->analyzeLast()));body.addView(button("采集文件与导出",()->startActivity(new Intent(this,FilesActivity.class))));body.addView(button("导入 PCAP 分析",()->pick(false)));body.addView(label("APK 静态分析",18));query=new EditText(this);query.setSingleLine();query.setHint("类名关键字，如 okhttp / ssl / CertificatePinner");query.setText("CertificatePinner");body.addView(query);body.addView(button("分析已安装美团 APK",()->installedApk("com.sankuai.meituan")));body.addView(button("导入 APK 分析",()->pick(true)));body.addView(button("生成安全测试流量",()->testTraffic()));body.addView(label("只需说明目标和内容。Eva 会处理普通设置与采集，系统要求授权时直接确认，返回后自动继续。",12));output=label("",12);output.setTextIsSelectable(true);body.addView(output);}
 Intent engine(String action){return new Intent(Intent.ACTION_VIEW).setClassName(ENGINE,ENGINE+".activities.CaptureCtrl").putExtra("action",action);}
 void startCapture(){
  if(requesting)return;requesting=true;String target=filter.getText().toString().trim();
  JSONObject args=new JSONObject();try{args.put("action","start").put("targetPackage",target.isEmpty()?"*":target).put("goal",goal.getText().toString()).put("decryptHttps",decrypt.isChecked());}catch(Exception ignored){}
  run(()->{try{return NetworkTools.execute(this,args).toString();}finally{runOnUiThread(()->requesting=false);}});
 }
 void command(String action,int code){run(()->NetworkTools.execute(this,new JSONObject().put("action",action.equals("get_status")?"status":action)).toString());}
 void showStatus(){if(status==null)return;status.setText(NetworkCaptureService.state+"\n范围："+(NetworkCaptureService.scope.isEmpty()?"全机":NetworkCaptureService.scope)+" · "+NetworkCaptureService.bytes+" 字节 / "+NetworkCaptureService.datagrams+" 个数据块");}
 void analyzeLast(){File f=NetworkCaptureService.file;if(f==null){String old=getSharedPreferences("eva-network",0).getString("lastFile","");try{if(!old.isEmpty())f=WorkspaceFiles.resolve(this,old);}catch(Exception ignored){}}if(f==null){output.setText("尚无采集文件");return;}File selected=f;if(NetworkCaptureService.active){output.setText("请先停止采集，再分析完整 PCAP");return;}run(()->{String json=PacketSummary.read(selected).json();saveReport(selected,json);return json;});}
 interface Task{String run()throws Exception;}void run(Task task){output.setText("正在分析…");work.execute(()->{String result;try{result=new JSONObject(task.run()).toString(2);}catch(Exception e){result="分析失败："+e.getMessage();}String text=result;runOnUiThread(()->{if(!isDestroyed())output.setText(text);});});}
 void saveReport(File source,String json)throws Exception{File report=WorkspaceFiles.resolve(this,"network-captures/report-"+System.currentTimeMillis()+".json");report.getParentFile().mkdirs();try(FileOutputStream out=new FileOutputStream(report)){out.write(json.getBytes("UTF-8"));}}
 void installedApk(String pkg){String q=query.getText().toString().trim();run(()->{android.content.pm.ApplicationInfo app=getPackageManager().getApplicationInfo(pkg,0);String report=ApkInventory.inspect(new File(app.sourceDir),q);saveReport(new File(app.sourceDir),report);return report;});}
 void pick(boolean apk){try{startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*"),apk?905:904);}catch(Exception e){output.setText("文件选择器不可用");}}
 protected void onActivityResult(int code,int result,Intent data){super.onActivityResult(code,result,data);if(code==901){requesting=false;if(result!=RESULT_OK){NetworkCaptureService.stop(this);output.setText("采集未获授权或启动失败；没有把失败标为已采集。");}else{File file=NetworkCaptureService.file;if(file!=null)try{String rel=WorkspaceFiles.root(this).toPath().relativize(file.toPath()).toString();getSharedPreferences("eva-network",0).edit().putString("lastFile",rel).commit();}catch(Exception ignored){}output.setText("引擎已接受启动；请操作目标 App，数据量增加后再停止分析。");}showStatus();}else if(code==902){if(result==RESULT_OK){NetworkCaptureService.stop(this);showStatus();}else output.setText("停止未确认，请到 PCAPdroid 查看状态。");}else if(code==903){boolean running=result==RESULT_OK&&data!=null&&data.getBooleanExtra("running",false);output.setText(result!=RESULT_OK?"引擎状态读取失败":running?"采集引擎运行中":"采集引擎已停止");if(result==RESULT_OK&&!running)NetworkCaptureService.stop(this);}else if((code==904||code==905)&&result==RESULT_OK&&data!=null&&data.getData()!=null){Uri uri=data.getData();String q=query.getText().toString().trim();run(()->{File f=WorkspaceFiles.resolve(this,"network-captures/import-"+System.currentTimeMillis()+(code==905?".apk":".pcap"));f.getParentFile().mkdirs();try(InputStream in=getContentResolver().openInputStream(uri);FileOutputStream out=new FileOutputStream(f)){if(in==null)throw new IOException("文件不可读取");byte[] b=new byte[32768];long total=0;int n;while((n=in.read(b))!=-1){total+=n;if(total>(code==905?512L:32L)*1024*1024)throw new IOException("文件超过分析上限");out.write(b,0,n);}}String json=code==905?ApkInventory.inspect(f,q):PacketSummary.read(f).json();saveReport(f,json);return json;});}}
 void testTraffic(){run(()->{java.net.HttpURLConnection c=(java.net.HttpURLConnection)new java.net.URL("https://example.org/").openConnection();c.setConnectTimeout(10000);c.setReadTimeout(10000);try{int status=c.getResponseCode();try(InputStream in=c.getInputStream()){byte[] b=new byte[1024];in.read(b);}return new JSONObject().put("testUrl","https://example.org/").put("httpStatus",status).put("captureBytes",NetworkCaptureService.bytes).toString();}finally{c.disconnect();}});}
 public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==907&&g.length>0&&g[0]==0)startCapture();}
 protected void onResume(){super.onResume();tick.post(refresh);}protected void onPause(){tick.removeCallbacks(refresh);super.onPause();}protected void onDestroy(){work.shutdownNow();super.onDestroy();}
}
